import { WORKFLOWS_TOPIC, WORKFLOWS_TOPIC_PREFIX } from '../command-ids.js';
import { collectOptionArguments } from './command-telemetry.js';
export function commandTraceContext(args) {
    const { commandId, argv, flagDefs, commandTelemetry, env } = args;
    return {
        groupOrCommand: WORKFLOWS_TOPIC,
        commandArguments: commandPath(commandId),
        extraArguments: collectOptionArguments({ argv, flagDefs, commandTelemetry }),
        coreOptions: {
            debug: Boolean(env.DEBUG),
            help: argv.includes('help'),
            version: argv.includes('--version'),
        },
    };
}
function commandPath(commandId) {
    if (commandId === undefined) {
        return [];
    }
    const path = commandId.startsWith(WORKFLOWS_TOPIC_PREFIX)
        ? commandId.slice(WORKFLOWS_TOPIC_PREFIX.length)
        : commandId;
    return path === '' || path === WORKFLOWS_TOPIC ? [] : path.split(':');
}
